/*\
Use Free Spaced Repetition Scheduler: https://github.com/open-spaced-repetition/free-spaced-repetition-scheduler
计算逻辑已上移 tidme/core（$:/plugins/keepone/tidme/core/fsrs），本模块仅为过滤器包装。
\*/

/*
Export our filter function
*/
(function () {

    /*jslint node: true, browser: true */
    /*global $tw: false */
    "use strict";

    var coreFsrs = require("$:/plugins/keepone/tidme/core/fsrs");

    /*
    Export our filter function
    */
    exports.fsrs = function (source, operator, options) {
        var results = [];
        source(function (tiddler, title) {
            if (tiddler) {
                results.push(coreFsrs.repeat(tiddler.fields, { p: operator.operand }));
            } else {
                results.push("");
            }
        });
        return results;
    };
})();

$:/plugins/keepone/tidme/review/fiters/s.text:
/*\
Filter operator for return a random title in the list.
\*/
(function () {

    /*jslint node: true, browser: true */
    /*global $tw: false */
    "use strict";

    /*
    Export our filter function
    */
    exports.sortrandom = function (source, operator, options) {
        var results = [];

        source(function (tiddler, title) {
            results.push(title);
        });

        results = results.sort(function () {
            return Math.random() - 0.5;
        });

        return results;
    };

})();

