	border-bottom: 1px solid var(--tm-border);
}
.tm-doc-table td {
	padding: 5px 12px;
	border-bottom: 1px solid var(--tm-border);
	color: var(--tm-text-1);
	vertical-align: middle;
	overflow: hidden;
	text-overflow: ellipsis;
	white-space: nowrap;
}
.tm-doc-table tbody tr:hover { background: var(--tm-surface-2); }
/* 已读区（名称弹性 / 操作固定右对齐） */
.tm-doc-done-table th:last-child, .tm-doc-done-table td:last-child { width: 130px; }
/* 摘录区（类型窄 / 名称弹性 / 加工窄 / 操作固定） */
.tm-doc-derived-table td:first-child, .tm-doc-derived-table th:first-child { width: 48px; }
.tm-doc-derived-table td:nth-child(3), .tm-doc-derived-table th:nth-child(3) { width: 80px; }
.tm-doc-derived-table td:nth-child(4), .tm-doc-derived-table th:nth-child(4) { width: 250px; }
.tm-cb-name { color: var(--tm-text-1); }
.tm-cb-actions { white-space: nowrap; text-align: right; }
.tm-cb-actions .tm-btn { margin-left: 4px; padding: 3px 10px; font-size: 0.84em; }
.tm-cb-del { color: var(--tm-text-2); }
.tm-cb-del:hover { color: var(--tm-danger); background: var(--tm-danger-soft); }
.tm-cb-kind {
	display: inline-flex;
	min-width: 1.7em;
	justify-content: center;
	font-size: 0.74em;
	border-radius: var(--tm-radius-sm);
	background: var(--tm-badge-new-bg);
	color: var(--tm-badge-new-fg);
	font-weight: 600;
	padding: 1px 4px;
}
.tm-doc-done-row {
	color: var(--tm-text-1);
}
.tm-doc-done-row:hover, .tm-doc-derived .tm-doc-done-row:hover { background: var(--tm-surface-2); }

/* M3 阅读态排版：Section 卡展开正文（与 section-bar 同帧时生效） */
.tc-tiddler-frame:has(.tm-section-bar) .tc-tiddler-body {
	max-width: 42em;
	line-height: 1.8;
}
.tc-tiddler-frame:has(.tm-section-bar) .tc-tiddler-body p {
	margin: 0.7em 0;
}
.tc-tiddler-frame:has(.tm-section-bar) .tc-tiddler-body h1,
.tc-tiddler-frame:has(.tm-section-bar) .tc-tiddler-body h2,
.tc-tiddler-frame:has(.tm-section-bar) .tc-tiddler-body h3 {
	margin-top: 1.2em;
}

/* 嵌套摘录 / 回看锚点高亮 */
.tm-inline-anchor {
	background: #d8ecff;
	box-shadow: 0 0 0 2px #d8ecff;
}
/* ===== W2 阅读列表（topic 队列页，卡片化） ===== */
.tm-reading-list {
	display: flex;
	flex-direction: column;
	gap: var(--tm-gap-xl);
}
.tm-rl-head {
	display: flex;
	align-items: center;
	flex-wrap: wrap;
	gap: 12px;
	padding-bottom: 12px;
	border-bottom: 1px solid var(--tm-border);
	margin-bottom: 8px;
}
.tm-rl-title {
	font-size: 1.25em;
	font-weight: 700;
	letter-spacing: -0.01em;
	color: var(--tm-text-1);
}
.tm-rl-sub {
	font-size: 0.86em;
	color: var(--tm-text-2);
}
.tm-rl-deck-btn {
	margin-left: auto;
}

.tm-rl-doc {
	border: 1px solid var(--tm-border);
	border-radius: var(--tm-radius);
	background: var(--tm-surface);
	box-shadow: var(--tm-shadow);
	overflow: hidden;
	transition: var(--tm-transition);
}
.tm-rl-doc:hover {
	box-shadow: var(--tm-shadow-lg);
	border-color: hsl(245, 75%, 85%);
	transform: translateY(-2px);
}
.tm-rl-doc-head {
	display: flex;
	align-items: center;
	gap: 12px;
	padding: 14px 18px;
	background: var(--tm-surface-2);
	border-bottom: 1px solid var(--tm-border);
	list-style: none;
	cursor: pointer;
	transition: var(--tm-transition);
}
.tm-rl-doc-head:hover {
	background: var(--tm-surface-3);
}
.tm-rl-doc[open] > .tm-rl-doc-head { border-bottom: 1px solid var(--tm-border); }
.tm-rl-doc-head::-webkit-details-marker { display: none; }
.tm-rl-doc-head::before { content: "▸"; color: var(--tm-text-3); transition: transform 0.2s; flex: none; font-size: 1.1em; }
.tm-rl-doc[open] > .tm-rl-doc-head::before { transform: rotate(90deg); }
.tm-rl-doc-head > .tc-tiddlylink { flex: 1; min-width: 0; color: var(--tm-text-1); font-weight: 600; }
.tm-rl-doc-head > .tc-tiddlylink:hover { color: var(--tm-accent); }
.tm-rl-doc-count { font-size: 0.8em; color: var(--tm-text-2); white-space: nowrap; }
.tm-rl-doc-name { font-weight: 700; color: var(--tm-text-1); font-size: 1.02em; }
.tm-rl-doc-prog { font-size: 0.82em; color: var(--tm-text-2); white-space: nowrap; }
.tm-rl-doc-bar { flex: 0 0 90px; height: 6px; margin: 0 4px; }
.tm-rl-table { width: 100%; border-collapse: collapse; font-size: 0.9em; }
.tm-rl-table th {
	text-align: left;
	padding: 6px 12px;
	color: var(--tm-text-3);
	font-size: 0.74em;
	text-transform: uppercase;
	letter-spacing: 0.02em;
	font-weight: 600;
	border-bottom: 1px solid var(--tm-border);
}
.tm-rl-table td {
	padding: 5px 12px;
	border-bottom: 1px solid var(--tm-border);
	color: var(--tm-text-1);
	vertical-align: middle;
}
.tm-rl-table tbody tr:hover { background: var(--tm-surface-2); }
.tm-rl-kind {
	display: inline-flex;
	min-width: 1.7em;
	justify-content: center;
	font-size: 0.74em;
	border-radius: var(--tm-radius-sm);
	background: var(--tm-badge-new-bg);
	color: var(--tm-badge-new-fg);
	font-weight: 600;
	padding: 1px 4px;
}
.tm-rl-kind-extract { background: var(--tm-badge-due-bg); color: var(--tm-badge-due-fg); }
.tm-rl-title { display: block; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.tm-rl-pri { font-size: 0.75em; color: var(--tm-text-3); font-variant-numeric: tabular-nums; }
.tm-rl-due {
	display: inline-block;
	font-size: 0.74em;
	padding: 0 8px;
	border-radius: 999px;
	font-weight: 600;
}
.tm-rl-row .tm-rl-due:empty { display: none; }

/* 侧边栏紧凑阅读列表 */
.tm-rl-compact .tm-rl-head { border-bottom: none; padding-bottom: 2px; }
.tm-rl-compact .tm-rl-title { font-size: 1em; }
.tm-rl-compact .tm-rl-doc-head { padding: 6px 8px; }
.tm-rl-compact .tm-rl-table { font-size: 0.82em; }
.tm-rl-compact .tm-rl-table th, .tm-rl-compact .tm-rl-table td { padding: 3px 8px; }


/* W3 摘录加工状态标注（文档页聚合区） */
.tm-cb-state {
	flex: none;
	font-size: 0.72em;
	padding: 0 6px;
	border-radius: var(--tm-radius);
	background: var(--tm-badge-new);
	opacity: 0.9;
}
.tm-cb-state-done { background: var(--tm-badge-due); }

/* ---- 仪表盘分栏网格 (Dashboard Grid Layout) ---- */
.tm-stats-grid {
	display: grid;
	grid-template-columns: 2fr 1fr;
	gap: 20px;
	margin-top: 20px;
}
.tm-stats-col-main {
	display: flex;
	flex-direction: column;
	gap: 18px;
}
.tm-stats-col-side {
	display: flex;
	flex-direction: column;
	gap: 18px;
}

@media (max-width: 768px) {
	.tm-stats-grid {
		grid-template-columns: 1fr;
	}
}

/* ---- 导入小部件容器与全页面拖拽覆盖层 (Uploader & Fullpage Drag Overlay) ---- */
.tm-import-widget {
	position: relative;
	width: 100%;
}
.tm-import-select-btn {
	display: block;
	width: 100%;
	padding: 14px 20px !important;
	font-size: 1.05em !important;
	font-weight: 600;
	border-radius: var(--tm-radius-sm) !important;
	text-align: center;
}
.tm-import-hint {
	font-size: 0.88em;
	color: var(--tm-text-3);
	text-align: center;
	margin: 10px 0 16px;
}
.tm-import-drag-overlay {
	position: absolute;
	top: 0;
	left: 0;
	right: 0;
	bottom: 0;
	background: rgba(99, 102, 241, 0.08);
	backdrop-filter: blur(4px);
	border: 2px dashed var(--tm-accent);
	border-radius: var(--tm-radius);
	display: flex;
	align-items: center;
	justify-content: center;
	color: var(--tm-accent-strong);
	font-size: 1.25em;
	font-weight: 700;
	z-index: 1000;
	pointer-events: none;
	transition: opacity 0.22s ease;
	text-align: center;
	padding: 20px;
}

/* ---- 粘贴文本 (Paste Split) & 收件箱 (Inbox Split) ---- */
.tm-paste-split {
	display: flex;
	flex-direction: column;
	gap: 12px;
}
.tm-paste-textarea {
	width: 100%;
	min-height: 180px;
	padding: 12px 14px;
	border: 1px solid var(--tm-border);
	border-radius: var(--tm-radius-sm);
	background: var(--tm-surface-2);
	color: var(--tm-text-1);
	font-family: var(--tm-font);
	font-size: 0.95em;
	outline: none;
	resize: vertical;
	transition: var(--tm-transition);
}
.tm-paste-textarea:focus {
	border-color: var(--tm-accent);
	background: var(--tm-surface);
	box-shadow: 0 0 0 3px var(--tm-accent-soft);
}
.tm-paste-split .tm-import-muted {
	font-size: 0.88em;
	color: var(--tm-text-3);
	margin-top: 4px;
}

/* 剪藏收件箱 */
.tm-inbox-split {
	display: flex;
	flex-direction: column;
	gap: 12px;
}
.tm-inbox-split .tm-import-row {
	display: flex;
	align-items: center;
	justify-content: space-between;
	padding: 10px 14px;
	border-bottom: 1px solid var(--tm-border);
	transition: var(--tm-transition);
}
.tm-inbox-split .tm-import-row:hover {
	background: var(--tm-surface-2);
}
.tm-inbox-split .tm-import-row strong {
	font-weight: 600;
	color: var(--tm-text-1);
	font-size: 0.95em;
}
.tm-inbox-split .tm-import-row button {
	padding: 5px 12px !important;
	font-size: 0.85em !important;
	border-radius: var(--tm-radius-xs) !important;
}

/* 统一导入中心选项卡现代下划线式导航 */
.tm-import-tabs {
	display: flex;
	gap: 28px;
	margin: 16px 0 24px;
	padding-bottom: 0;
	border-bottom: 2px solid var(--tm-border);
}
.tm-import-tabs label.tm-import-tab {
	display: inline-flex;
	align-items: center;
	position: relative;
	font-size: 0.95em;
	font-weight: 600;
	color: var(--tm-text-2);
	padding: 8px 4px 12px;
	cursor: pointer;
	border: none !important;
	border-radius: 0 !important;
	background: transparent !important;
	border-bottom: 2px solid transparent !important;
	margin-bottom: -2px;
	transition: var(--tm-transition);
	box-shadow: none !important;
}
.tm-import-tabs label.tm-import-tab input[type="radio"] {
	display: none !important;
}
.tm-import-tabs label.tm-import-tab:hover {
	color: var(--tm-accent) !important;
}
.tm-import-tabs label.tm-import-tab.tm-tab--active,
.tm-import-tabs label.tm-import-tab.tc-radio-selected {
	color: var(--tm-accent) !important;
	border-bottom: 2px solid var(--tm-accent) !important;
	font-weight: 700;
}

/* AI 切分配置面板与大纲编辑器 */
.tm-ai-config-panel {
	margin: 8px 0 12px;
	border: 1px dashed var(--tm-accent);
	border-radius: var(--tm-radius);
	padding: 6px 12px;
	background: var(--tm-surface-2);
}
.tm-ai-config-summary {
	cursor: pointer;
	font-weight: 600;
	color: var(--tm-accent);
}
.tm-ai-config-body {
	margin-top: 8px;
	display: flex;
	flex-direction: column;
	gap: 6px;
}
.tm-ai-inputs-row {
	display: flex;
	gap: 6px;
	flex-wrap: wrap;
}
.tm-ai-inputs-row .tm-input {
	flex: 1;
	min-width: 140px;
}
.tm-split-row-renamed {
	border-left: 3px solid var(--tm-accent) !important;
}
.tm-split-row-deleted {
	opacity: 0.45;
	text-decoration: line-through;
	background: var(--tm-surface-2);
}
.tm-split-title-input {
	font-size: 0.9em;
	padding: 2px 6px;
	border: 1px solid var(--tm-accent);
	border-radius: 4px;
	background: var(--tm-surface);
	color: var(--tm-text-1);
}
.tm-split-add-form {
	margin: 6px 0 6px 20px;
	padding: 8px;
	border: 1px solid var(--tm-border);
	border-radius: var(--tm-radius);
	background: var(--tm-surface-2);
	display: flex;
	flex-direction: column;
	gap: 6px;
}
.tm-split-chars-warn {
	background: #ffe8cc !important;
	color: #d97706 !important;
	font-weight: 600;
}


/* ----- From manager\styles.tid ----- */
/* Tidme Manager：卡片浏览 / 管理器 / 牌组批量操作样式 */

/* 设计 token / tm-btn 基类统一由 $:/plugins/keepone/tidme/core/styles/tokens 提供 */
/* ===== 按钮：tm-btn 基类与变体统一由 core/styles/tokens 提供；此处仅图标尺寸 ===== */
.tm-btn-icon { padding: 2px 6px; }
.tm-btn-icon img, .tm-btn-icon svg { width: 1em; height: 1em; vertical-align: -0.15em; }

/* ===== 空状态（tm-empty：图标 + 说明 + 可选主操作） ===== */
.tm-empty {
	display: flex;
	flex-direction: column;
	align-items: center;
	gap: var(--tm-gap);
	padding: 18px 8px;
	color: var(--tm-text-2);
	font-size: 0.9em;
	text-align: center;
}
.tm-empty-icon { font-size: 1.8em; opacity: 0.45; line-height: 1; }

/* ===== Toast 反馈（P3 接入写库动作；tm-notify 通知模板的自定义样式） ===== */
.tm-toast {
	padding: 6px 12px;
	border-radius: var(--tm-radius);
	border: 1px solid var(--tm-text-2);
	background: var(--tm-surface);
	font-size: 0.9em;
	box-shadow: 0 2px 8px rgba(0, 0, 0, 0.12);
}
.tm-toast--ok { border-color: #22c55e; color: #15803d; }
.tm-toast--err { border-color: var(--tm-danger); color: var(--tm-danger); }

/* 卡片浏览（侧边栏树形） */
.tm-card-browser details {
	margin-left: 0.4em;
}
.tm-card-browser summary {
	cursor: pointer;
}
.tm-cb-deck {
	margin-top: 0.4em;
}
.tm-cb-doc {
	margin-left: 0.6em;
	padding-left: 0.5em;
	border-left: 2px solid var(--tm-text-2);
	opacity: 0.9;
}
.tm-cb-doc-title {
	opacity: 0.85;
	font-size: 0.95em;
}
.tm-cb-card {
	display: flex;
	align-items: center;
	gap: 0.3em;
	font-size: 0.9em;
	padding: 1px 0;
}
.tm-cb-badge {
	font-size: 0.85em;
	opacity: 0.8;
	min-width: 1.2em;
}
.tm-cb-kind {
	font-size: 0.8em;
	opacity: 0.6;
}
.tm-cb-link {
	overflow: hidden;
	text-overflow: ellipsis;
	white-space: nowrap;
	max-width: 16em;
}
.tm-cb-del {
	opacity: 0.4;
	padding: 0 4px;
}
.tm-cb-del:hover {
	opacity: 1;
}

/* 卡片管理器 */
.tm-card-manager {
	font-size: 0.95em;
}
.tm-cm-toolbar {
	position: sticky;
	top: 0;
	z-index: 60;
	background: var(--tm-surface);
	padding: 8px 0 10px;
	margin-bottom: 6px;
	border-bottom: 1px solid var(--tm-border);
	box-shadow: 0 2px 8px rgba(17, 24, 39, 0.05);
}
.tm-cm-top-row {
	display: flex;
	align-items: center;
	gap: 14px;
	flex-wrap: wrap;
	margin-bottom: 12px;
}
.tm-cm-search-row { display: flex; gap: 6px; align-items: center; }
.tm-cm-search {
	flex: 1;
	max-width: 260px;
	padding: 6px 12px;
	font-size: 0.85em;
	font-family: var(--tm-font);
	border: 1px solid var(--tm-border);
	border-radius: var(--tm-radius-sm);
	background: var(--tm-surface-2);
	color: var(--tm-text-1);
}
.tm-cm-search:focus { outline: 2px solid var(--tm-accent-soft); border-color: var(--tm-accent); }
.tm-cm-clear { padding: 4px 10px; }
/* 卡片主体：限高内滚动（大量卡片不撑长页面，工具栏 sticky 固定） */
.tm-cm-body { max-height: 62vh; overflow-y: auto; }
.tm-cm-body::-webkit-scrollbar { width: 8px; }
.tm-cm-body::-webkit-scrollbar-thumb { background: var(--tm-border); border-radius: 999px; }
.tm-cm-body::-webkit-scrollbar-thumb:hover { background: var(--tm-text-3); }
.tm-cm-views {
	display: flex;
	gap: 6px;
	flex-wrap: wrap;
}
.tm-cm-view {
	padding: 4px 14px;
	border-radius: 999px;
	border: 1px solid var(--tm-border);
	background: var(--tm-surface);
	color: var(--tm-text-2);
	font-size: 0.84em;
	font-weight: 550;
	cursor: pointer;
	transition: var(--tm-transition);
}
.tm-cm-view:hover {
	color: var(--tm-text-1);
	border-color: hsl(220, 10%, 75%);
}
.tm-cm-view-active {
	background: var(--tm-accent);
	border-color: var(--tm-accent);
	color: #fff;
	box-shadow: var(--tm-shadow-sm);
}
.tm-cm-orgs {
	display: flex;
	gap: 6px;
	flex-wrap: wrap;
}
.tm-cm-org {
	padding: 3px 12px;
	border-radius: 999px;
	border: 1px solid var(--tm-border);
	background: var(--tm-surface);
	color: var(--tm-text-2);
	font-size: 0.82em;
	font-weight: 550;
	cursor: pointer;
	transition: var(--tm-transition);
}
.tm-cm-org:hover {
	color: var(--tm-text-1);
	border-color: hsl(220, 10%, 75%);
}
.tm-cm-org-active {
	border-style: solid;
	border-color: var(--tm-accent);
	color: var(--tm-accent-strong);
	background: var(--tm-accent-soft);
}
.tm-cm-bar {
	display: flex;
	flex-direction: column;
	gap: 10px;
	align-items: stretch;
	margin-bottom: 14px;
	padding: 12px 14px;
	border: 1px solid var(--tm-border);
	border-radius: var(--tm-radius-sm);
	background: var(--tm-surface-2);
}
.tm-cm-bar-row {
	display: flex;
	align-items: center;
	gap: 8px;
	flex-wrap: wrap;
}
.tm-cm-bar button {
	font-size: 0.82em;
	padding: 5px 12px;
	background: var(--tm-surface);
	border: 1px solid var(--tm-border);
	border-radius: var(--tm-radius-sm);
	color: var(--tm-text-2);
	font-weight: 550;
	cursor: pointer;
	transition: var(--tm-transition);
}
.tm-cm-bar button:hover {
	background: var(--tm-surface);
	border-color: hsl(220, 10%, 70%);
	color: var(--tm-text-1);
	transform: translateY(-0.5px);
	box-shadow: var(--tm-shadow-sm);
}
.tm-cm-tree details {
	margin-left: 0.4em;
}
.tm-cm-tree summary,
.tm-cm-body summary {
	display: flex;
	align-items: center;
	gap: 6px;
	cursor: pointer;
}
.tm-cm-group-cb {
	margin: 0 4px 0 0;
	cursor: pointer;
}
.tm-cm-sel-info {
	font-size: 0.82em;
	color: var(--tm-text-2);
	font-weight: 550;
	vertical-align: middle;
}
.tm-cm-deck {
	margin-top: 0.4em;
}
.tm-cm-doc {
	margin-left: 0.8em;
	padding-left: 0.5em;
	border-left: 2px solid var(--tm-border);
}
.tm-cm-doc-title {
	font-weight: 600;
	font-size: 0.95em;
}
.tm-cm-card {
	display: flex;
	align-items: center;
	gap: 0.35em;
	padding: 2px 0;
}
.tm-cm-head {
	border-bottom: 1px dotted var(--tm-text-2);
	margin-bottom: 2px;
	font-size: 0.85em;
	opacity: 0.8;
}
.tm-cm-head-cell {
