}
.tm-cm-sort {
	padding: 0 4px;
	font-size: 0.9em;
	border-radius: 3px;
	border: 1px solid transparent;
}
.tm-cm-sort:hover {
	border-color: var(--tm-text-2);
}
.tm-cm-sort-active {
	border-color: var(--tm-accent);
	color: var(--tm-accent);
}
.tm-cm-listrow {
	font-size: 0.9em;
}
.tm-cm-col-deck {
	font-size: 0.8em;
	opacity: 0.6;
	min-width: 6em;
	max-width: 10em;
	overflow: hidden;
	text-overflow: ellipsis;
	white-space: nowrap;
}
.tm-cm-col-due {
	font-size: 0.8em;
	opacity: 0.6;
	min-width: 5em;
}
/* 卡片信息列（对标 SuperMemo Element data） */
.tm-cm-col-info {
	font-size: 0.8em;
	opacity: 0.65;
	min-width: 4em;
}
/* 卡片列表真表格（P2） */
.tm-cm-table {
	border-collapse: collapse;
	width: 100%;
	font-size: 0.92em;
}
.tm-cm-table th,
.tm-cm-table td {
	border-bottom: 1px solid var(--tm-text-2);
	padding: 2px 6px;
	text-align: left;
	vertical-align: middle;
}
.tm-cm-table thead th {
	position: sticky;
	top: 0;
	background: var(--tm-surface);
	opacity: 0.9;
	font-weight: 500;
	z-index: 1;
	white-space: nowrap;
}
.tm-cm-table tbody tr:hover td {
	background: var(--tm-surface-2);
}
.tm-cm-table tbody tr.tm-cm-listrow-selected td {
	background: var(--tm-surface-2);
}
.tm-cm-cell-cb {
	width: 2em;
	text-align: center;
}
.tm-cm-cell-flex {
	display: flex;
	align-items: center;
	gap: 0.35em;
}
.tm-cm-listrow {
	cursor: pointer;
}

.tm-cm-preview {
	margin: 6px 0 2px;
	padding: 6px 8px;
	border: 1px solid var(--tm-text-2);
	border-radius: 4px;
	background: var(--tm-surface-2);
}
.tm-cm-preview-head {
	font-size: 0.85em;
	opacity: 0.8;
	margin-bottom: 3px;
}
.tm-cm-preview-body {
	font-size: 0.9em;
	max-height: 10em;
	overflow: auto;
	white-space: pre-wrap;
}
/* 卡片信息明细（对标 Element data 分组） */
.tm-cm-info-grid {
	display: grid;
	grid-template-columns: repeat(auto-fill, minmax(11em, 1fr));
	gap: 2px 12px;
	font-size: 0.85em;
	margin: 3px 0;
}
.tm-cm-info-grid span {
	overflow: hidden;
	text-overflow: ellipsis;
	white-space: nowrap;
}
.tm-cm-info-label {
	opacity: 0.55;
	margin-right: 0.4em;
}
/* 单卡参数编辑（对标 Element parameters） */
.tm-cm-edit {
	margin: 4px 0 2px;
	padding: 4px 8px;
	border: 1px dashed var(--tm-text-2);
	border-radius: 4px;
	font-size: 0.9em;
}
.tm-cm-edit-row {
	display: flex;
	align-items: center;
	gap: 0.5em;
	margin: 3px 0;
	flex-wrap: wrap;
}
.tm-cm-edit-row input[type="text"],
.tm-cm-edit-row input[type="number"] {
	width: 12em;
}
/* 牌组批量操作卡片（P2） */
.tm-queue-card {
	border: 1px solid var(--tm-text-2);
	border-radius: var(--tm-radius);
	padding: 6px 10px;
	margin: 6px 0;
	background: var(--tm-surface);
}
.tm-queue-card-head {
	display: flex;
	align-items: baseline;
	gap: var(--tm-gap-lg);
	margin-bottom: 4px;
}
.tm-queue-card-count {
	font-size: 0.85em;
	opacity: 0.65;
}
.tm-queue-card-btns {
	display: flex;
	gap: var(--tm-gap);
	flex-wrap: wrap;
}

.tm-cm-orphan summary strong {
	opacity: 0.65;
	font-style: italic;
}
.tm-cm-bar-group {
	display: inline-flex;
	gap: 6px;
	border-right: 1px solid var(--tm-border);
	padding-right: 10px;
	margin-right: 4px;
	align-items: center;
}
.tm-cm-bar-group:last-child {
	border-right: none;
	padding-right: 0;
	margin-right: 0;
}
.tm-cm-badge {
	font-size: 0.8em;
	padding: 2px 8px;
	min-width: 2em;
	height: 1.6em;
	font-weight: 600;
	border-radius: 999px;
}
.tm-badge-new { background: var(--tm-badge-new-bg); color: var(--tm-badge-new-fg); }
.tm-badge-learn { background: var(--tm-badge-learn-bg); color: var(--tm-badge-learn-fg); }
.tm-badge-due { background: var(--tm-badge-due-bg); color: var(--tm-badge-due-fg); }
.tm-badge-overdue { background: var(--tm-badge-overdue-bg); color: var(--tm-badge-overdue-fg); }
.tm-badge-done { background: hsl(220, 14%, 90%); color: hsl(220, 10%, 40%); opacity: 0.9; }
.tm-badge-suspended { background: var(--tm-badge-suspended-bg); color: var(--tm-badge-suspended-fg); }
.tm-cm-kind {
	display: inline-flex;
	align-items: center;
	justify-content: center;
	font-size: 0.74em;
	font-weight: 600;
	border-radius: var(--tm-radius-xs);
	padding: 1px 5px;
	margin: 0 4px;
	background: var(--tm-badge-new-bg);
	color: var(--tm-badge-new-fg);
}
.tm-cm-pri {
	display: inline-flex;
	align-items: center;
	justify-content: center;
	font-size: 0.76em;
	font-weight: 600;
	color: var(--tm-text-2);
	background: var(--tm-surface-3);
	border-radius: var(--tm-radius-xs);
	padding: 1px 6px;
	margin: 0 4px;
	font-family: var(--tm-font-mono);
}
.tm-cm-link {
	overflow: hidden;
	text-overflow: ellipsis;
	white-space: nowrap;
	max-width: 22em;
	font-weight: 550;
}
.tm-cm-op {
	display: inline-flex;
	align-items: center;
	justify-content: center;
	padding: 3px 8px;
	font-size: 0.78em;
	font-weight: 600;
	border: 1px solid var(--tm-border);
	border-radius: var(--tm-radius-xs);
	background: var(--tm-surface-2);
	color: var(--tm-text-2);
	cursor: pointer;
	margin-left: 4px;
	transition: var(--tm-transition);
}
.tm-cm-op:hover {
	background: var(--tm-surface-3);
	color: var(--tm-text-1);
	border-color: hsl(220, 10%, 75%);
}
.tm-cm-del:hover {
	color: var(--tm-danger);
	background: var(--tm-danger-soft);
	border-color: transparent;
}


/* ----- From read\styles.tid ----- */
.tmc-annotation-wrapper {
    min-width: 500px;
    transform: scale(0.7);
    transform-origin: top left;
    overflow-y:hidden;
}

.tmc-annotation-wrapper .tc-drop-down button{
    padding: 7px 14px;;
}


/* ----- From review\styles.tid ----- */
.tmc-thead{
    display:flex;
    justify-content: space-between;
    align-items:center;
    font-weight: bold;
    border-bottom: 1px solid var(--tm-border);
    padding-bottom:10px;
}

.tmc-tr{
    display:flex;
    justify-content: space-between;
    align-items:center;
    padding:10px 0;
}

.tmc-tr .tmc-button-show{
    margin: 0 3px !important;
    flex-shrink: 0;
}

.tmc-tr .tmc-button-hide{
    opacity: 0;
    margin: 0 3px !important;
    flex-shrink: 0;
}

.tmc-tr:hover {
    background-color: var(--tm-surface-2);
}

.tmc-tr:hover .tmc-button-hide{
    opacity: 1 !important;
}

.tmc-tr-deck{
    flex:0 1 40%;
    display: flex;
    justify-content:flex-start;
}


.tmc-tr-study{
    flex:0 1 15%;
    display: flex;
    justify-content:center;
}

.tmc-tr-action{
    flex:0 1 15%;
    display: flex;
    justify-content:flex-end;
}



.tmc-btn-primary {
    background: var(--tm-accent);
    color: var(--tm-surface);
    fill: var(--tm-surface);
}

.tmc-btn-dirty {
    background: var(--tm-warn);
    color: var(--tm-surface);
    fill: var(--tm-surface);
}

.tmc-btn-dirty {
    background: var(--tm-warn);
    color: var(--tm-surface);
    fill: var(--tm-surface);
}

/* 复习评分条：sticky 顶部固定，长卡片评分随手可点 */
.tmc-study-bar {
    position: sticky;
    top: 0;
    z-index: 60;
    background: var(--tm-surface);
    padding: 4px 0 6px;
    border-bottom: 1px solid var(--tm-border);
}
.tmc-study-count { font-size: 10px; color: var(--tm-text-2); }

.tmc-repeat-wrapper {
	display: grid;
	grid-template-columns: repeat(4, 1fr);
	gap: 10px;
	margin: 16px 0 10px;
	width: 100%;
}
.tmc-repeat-wrapper button {
	display: flex;
	flex-direction: column;
	align-items: center;
	justify-content: center;
	padding: 10px 8px;
	border-radius: var(--tm-radius-sm) !important;
	border: 1px solid var(--tm-border) !important;
	background: var(--tm-surface) !important;
	box-shadow: var(--tm-shadow-sm);
	cursor: pointer;
	text-decoration: none !important;
	transition: var(--tm-transition) !important;
	width: 100%;
}
.tmc-repeat-wrapper button:hover {
	transform: translateY(-2px);
	box-shadow: var(--tm-shadow-md);
	border-color: currentColor !important;
	background: var(--tm-surface-2) !important;
}

.tmc-repeat-wrapper-1 {
	display: flex;
	justify-content: center;
	margin-top: 16px;
}

.tmc-decks-button-wrapper{
    display:flex;
    justify-content: space-around;
    align-items: baseline;
}

.tmc-file-input-wrapper {
    position: relative;
    overflow: hidden;
    vertical-align: middle;
}

.tmc-file-input-wrapper input[type=file] {
    position: absolute;
    top: 0;
    left: 0;
    right: 0;
    bottom: 0;
    font-size: 999px;
    max-width: 100%;
    max-height: 100%;
    filter: alpha(opacity=0);
    opacity: 0;
    outline: none;
    background: white;
    cursor: pointer;
